values
  ('baytown-3br-house', 'approved', 'Furnished 3-Bed House Near the Refineries', 'house', 3, 2, 2200, '1-6 months', 'Clean, fully furnished 3-bedroom house minutes from the plants. Full kitchen, washer/dryer, fenced yard and plenty of truck parking. Move-in ready for a crew or a single worker.', 'Minutes from ExxonMobil Baytown and Chevron Phillips. Close to ongoing turnaround work.', array['Wi-Fi', 'Washer/Dryer', 'Truck/RV parking', 'Fenced yard', 'Fully furnished']::text[], true, 'case_by_case', 'Baytown', 'TX', 'Baytown, TX', 29.74, -94.98, '(281) 555-0142', true, NULL, false, true, array['https://picsum.photos/seed/bch-baytown-1/1200/800', 'https://picsum.photos/seed/bch-baytown-2/1200/800', 'https://picsum.photos/seed/bch-baytown-3/1200/800']::text[]),
  ('port-arthur-2br-apt', 'approved', '2-Bed Apartment, Bills Paid', 'apartment', 2, 1, 1650, 'Month to month', 'Comfortable 2-bedroom apartment with all bills paid. Furnished, quiet complex, easy in and out for shift work. Close to Motiva and Valero.', 'Walking distance to Motiva Port Arthur. Near Valero and ongoing shutdown projects.', array['Wi-Fi', 'All utilities included', 'Furnished', 'Off-street parking']::text[], true, 'no', 'Port Arthur', 'TX', 'Port Arthur, TX', 29.88, -93.93, '(409) 555-0188', true, 'portarthur.rentals@example.com', true, true, array['https://picsum.photos/seed/bch-portarthur-1/1200/800', 'https://picsum.photos/seed/bch-portarthur-2/1200/800']::text[]),
  ('midland-rv-pad', 'approved', 'Full-Hookup RV Pad in Quiet Lot', 'rv', 0, 0, 850, 'Weekly or monthly', 'Level concrete RV pad with full hookups (30/50 amp, water, sewer). Quiet, gated lot with easy access to the highway. Perfect for oilfield work.', 'Central to Permian Basin oilfield work. Easy reach of Midland and Odessa job sites.', array['30/50 amp', 'Water & sewer', 'Gated', 'Truck/RV parking']::text[], false, 'allowed', 'Midland', 'TX', 'Midland, TX', 31.99, -102.08, '(432) 555-0119', true, NULL, false, true, array['https://picsum.photos/seed/bch-midland-1/1200/800', 'https://picsum.photos/seed/bch-midland-2/1200/800']::text[]),
  ('odessa-4br-crew-house', 'approved', '4-Bed Crew House, Sleeps 6', 'house', 4, 2, 3200, '1-12 months', 'Spacious crew-friendly house set up for a team. Six beds, two full baths, big kitchen and a large gravel lot for trucks and trailers. Bring the whole crew.', 'Built for Permian Basin crews. Close to oilfield and plant expansion projects around Odessa.', array['Wi-Fi', 'Washer/Dryer', 'Crew-friendly / multiple beds', 'Truck/RV parking', 'Fully furnished']::text[], false, 'case_by_case', 'Odessa', 'TX', 'Odessa, TX', 31.85, -102.37, '(432) 555-0177', true, NULL, false, true, array['https://picsum.photos/seed/bch-odessa-1/1200/800', 'https://picsum.photos/seed/bch-odessa-2/1200/800', 'https://picsum.photos/seed/bch-odessa-3/1200/800']::text[]),
  ('lake-charles-1br-cabin', 'approved', 'Private 1-Bed Cabin', 'cabin', 1, 1, 1400, 'Month to month', 'Cozy private cabin for one or two. Furnished, quiet and private with a small porch. Good base for turnaround and construction work around Lake Charles.', 'Near Citgo and Phillips 66 Lake Charles. Close to LNG and petrochemical projects.', array['Wi-Fi', 'Furnished', 'Private entrance', 'Truck parking']::text[], true, 'no', 'Lake Charles', 'LA', 'Lake Charles, LA', 30.23, -93.22, '(337) 555-0151', true, NULL, false, true, array['https://picsum.photos/seed/bch-lakecharles-1/1200/800', 'https://picsum.photos/seed/bch-lakecharles-2/1200/800']::text[]),
  ('sulphur-2br-duplex', 'approved', '2-Bed Duplex, Newly Furnished', 'duplex', 2, 1, 1500, '1-3 months', 'Newly furnished half of a clean duplex. Two bedrooms, full kitchen, washer/dryer hookups. Quiet street, easy parking, ready for shift workers.', 'Close to Westlake and Sulphur area plants. Convenient to ongoing turnaround work.', array['Wi-Fi', 'Washer/Dryer', 'Furnished', 'Off-street parking']::text[], false, 'case_by_case', 'Sulphur', 'LA', 'Sulphur, LA', 30.24, -93.38, '(337) 555-0193', true, NULL, false, true, array['https://picsum.photos/seed/bch-sulphur-1/1200/800', 'https://picsum.photos/seed/bch-sulphur-2/1200/800']::text[]),
  ('baton-rouge-room', 'approved', 'Private Room in Quiet Home', 'room', 1, 1, 900, 'Month to month', 'Furnished private room with its own bathroom in a quiet, clean home. Shared kitchen and laundry. Great budget option for a single worker.', 'Near ExxonMobil Baton Rouge and area chemical plants. Easy highway access.', array['Wi-Fi', 'Furnished', 'Private bath', 'Shared laundry']::text[], true, 'no', 'Baton Rouge', 'LA', 'Baton Rouge, LA', 30.45, -91.15, '(225) 555-0166', true, NULL, false, true, array['https://picsum.photos/seed/bch-batonrouge-1/1200/800']::text[]),
  ('williston-3br-house', 'approved', '3-Bed House Built for Winters', 'house', 3, 2, 2600, '1-12 months', 'Warm, fully furnished 3-bedroom house set up for Bakken winters. Heated garage, washer/dryer, plowed drive. Plenty of room for trucks and gear.', 'Heart of the Bakken. Close to oilfield, pipeline and rig work around Williston.', array['Wi-Fi', 'Washer/Dryer', 'Heated garage', 'Truck/RV parking', 'Fully furnished']::text[], false, 'allowed', 'Williston', 'ND', 'Williston, ND', 48.15, -103.62, '(701) 555-0124', true, NULL, false, true, array['https://picsum.photos/seed/bch-williston-1/1200/800', 'https://picsum.photos/seed/bch-williston-2/1200/800']::text[]),
  ('carlsbad-2br-mobile', 'approved', '2-Bed Mobile Home, Oilfield Ready', 'mobile-home', 2, 1, 1300, 'Month to month', 'Clean, furnished 2-bedroom mobile home on a private lot. Big yard, room for trucks and trailers, quiet at night so you can rest between shifts.', 'Central to Permian Basin work near Carlsbad. Close to potash and oilfield projects.', array['Wi-Fi', 'Furnished', 'Truck/RV parking', 'Large lot']::text[], false, 'allowed', 'Carlsbad', 'NM', 'Carlsbad, NM', 32.42, -104.23, '(575) 555-0138', true, NULL, false, true, array['https://picsum.photos/seed/bch-carlsbad-1/1200/800', 'https://picsum.photos/seed/bch-carlsbad-2/1200/800']::text[]),
  ('hobbs-rv-lot', 'approved', 'Monthly RV Lot with Full Hookups', 'rv', 0, 0, 800, 'Monthly', 'Spacious pull-through RV lot with full hookups and 50 amp service. Gravel pad, good lighting, quiet and secure. Easy access for big rigs.', 'Close to Permian oilfield work around Hobbs. Quick highway access to job sites.', array['50 amp', 'Water & sewer', 'Pull-through', 'Truck/RV parking']::text[], false, 'allowed', 'Hobbs', 'NM', 'Hobbs, NM', 32.7, -103.14, '(575) 555-0107', true, NULL, false, true, array['https://picsum.photos/seed/bch-hobbs-1/1200/800']::text[]),
  ('texas-city-2br-house', 'approved', '2-Bed House Near the Plants', 'house', 2, 1, 1900, '1-6 months', 'Tidy furnished 2-bedroom house close to the Texas City plants. Full kitchen, washer/dryer, driveway parking and a small yard. Comfortable and quiet.', 'Near Marathon Galveston Bay and Valero Texas City. Close to turnaround and shutdown work.', array['Wi-Fi', 'Washer/Dryer', 'Furnished', 'Driveway parking']::text[], true, 'case_by_case', 'Texas City', 'TX', 'Texas City, TX', 29.38, -94.9, '(409) 555-0172', true, NULL, false, true, array['https://picsum.photos/seed/bch-texascity-1/1200/800', 'https://picsum.photos/seed/bch-texascity-2/1200/800']::text[]),
  ('freeport-1br-apt', 'approved', '1-Bed Apartment, Walk to the Gate', 'apartment', 1, 1, 1350, 'Month to month', 'Simple, clean 1-bedroom apartment a short drive from the Freeport plants. Furnished with the basics, bills paid, easy parking. Good single-worker option.', 'Minutes from Dow Freeport and area LNG projects. Convenient to ongoing plant work.', array['Wi-Fi', 'All utilities included', 'Furnished', 'Off-street parking']::text[], true, 'no', 'Freeport', 'TX', 'Freeport, TX', 28.95, -95.36, '(979) 555-0145', true, NULL, false, true, array['https://picsum.photos/seed/bch-freeport-1/1200/800', 'https://picsum.photos/seed/bch-freeport-2/1200/800']::text[])
